function kind(input) {return input.book?.kind || input.contentKind || input.settings.mode || 'novel';}
function rows(value,nori) {
  if(typeof value==='string'){try{value=JSON.parse(value);}catch{nori.fail('value_invalid','条目规则未返回 JSON','/items');}}
  if(Array.isArray(value))return value;
  if(value && typeof value==='object')return [value];
  if(value===null || value===undefined)return [];
  nori.fail('value_invalid','条目规则必须返回数组或对象','/items');
}
function text(value) {return value===null || value===undefined?'':Array.isArray(value)?value.join(','):typeof value==='object'?JSON.stringify(value):String(value);}
