function dataURL(name,value,nori) {
  if(typeof value==='string')return `data:;base64,${nori.codec.base64Encode(value)}`;
  return `data:${name};base64,${nori.codec.base64Encode(JSON.stringify(value))},{"type":"susan"}`;
