  let decoded;
  try{decoded=nori.codec.base64Decode(match[2]);}catch{nori.fail('value_invalid','内部定位数据不是 Base64','/locator');}
  if(!match[1])return decoded;
  try{return JSON.parse(decoded);}catch{nori.fail('value_invalid','内部定位数据不是 JSON','/locator');}
}
async function load(programs,address,nori) {
