    if(value!==null && value!==undefined && text(value).trim())return value;
  }
  if(Object.hasOwn(row,'handle')) {
    const value=programs.queryDOM(row,selector,mode,false);
    if(value!==null && value!==undefined && text(value).trim())return value;
    const ownText=programs.queryValue(row,'text',false);
